/**
 * The basemap, drawn from theme tokens.
 *
 * A hosted map style ships its colours baked in, which gives you exactly two
 * maps: a light one and a dark one. PanelUI has six themes, and a map that
 * stays grey while the rest of the screen turns green is the one element on
 * the page that visibly does not belong to it.
 *
 * So the style is assembled here instead. Tiles still come from the vector
 * source — that is the part worth paying someone for — but every colour in
 * the style is a token the caller's theme already resolved, which means a new
 * theme gets a matching basemap without anyone drawing one.
 *
 * The layer list is deliberately short. A full street style runs to ninety-odd
 * layers separating tunnel casings from bridge casings at eleven zoom stops;
 * almost none of that survives being recoloured down to five greys, and every
 * layer is another thing to keep in step with the tokens. What is here is the
 * set that still reads as a map at any zoom: ground, water, green space,
 * buildings, roads, boundaries, and the labels that make them findable.
 */
import type { StyleSpecification } from '@/components/ui/maplibre';

/** Resolved theme colours the style is built from. */
export interface BasemapTokens {
  /** Ground — everything that is not something else. */
  background: string;
  /** Water bodies and rivers. */
  water: string;
  /** Parks, forest, and other green space. */
  land: string;
  /** Building footprints. */
  building: string;
  /** Roads, boundaries and other lines. */
  line: string;
  /** Label text. */
  label: string;
  /** Halo behind label text, so it stays legible over any fill. */
  labelHalo: string;
}

/**
 * Vector tiles and the glyphs to label them with.
 *
 * Swappable because the tiles are the one part of the style that is somebody
 * else's to license. The defaults follow the OpenMapTiles schema, so any
 * source using it can be dropped in without touching the layers below.
 */
export interface BasemapSource {
  /** TileJSON URL for the vector source. */
  url: string;
  /** Glyph endpoint, `{fontstack}` and `{range}` templated. */
  glyphs: string;
  /** Font stack for labels. Needs to exist at the glyph endpoint. */
  fonts: string[];
  /** Shown in the attribution control. Check your provider's terms. */
  attribution?: string;
}

/**
 * CARTO's street tiles.
 *
 * Free for non-commercial use; commercial use needs a licence from them. Pass
 * your own `BasemapSource` to use a different provider — the layers below only
 * assume the OpenMapTiles schema, which most vector providers serve.
 */
export const CARTO_SOURCE: BasemapSource = {
  url: 'https://tiles.basemaps.cartocdn.com/vector/carto.streets/v1/tiles.json',
  glyphs: 'https://tiles.basemaps.cartocdn.com/fonts/{fontstack}/{range}.pbf',
  fonts: ['Montserrat Regular', 'Open Sans Regular', 'Noto Sans Regular'],
  attribution: '© OpenStreetMap contributors, © CARTO',
};

const SOURCE_ID = 'basemap';

/**
 * Widths that hold up across the whole zoom range.
 *
 * A road drawn at a fixed width is a hairline at zoom 5 and a runway at zoom
 * 18, so each class interpolates between the zoom it appears at and the zoom
 * it stops growing. Exponential rather than linear because zoom itself is
 * exponential — a linear ramp makes every road look identical for the first
 * half of the range and then explodes.
 */
function width(stops: [number, number][]) {
  return [
    'interpolate',
    ['exponential', 1.5],
    ['zoom'],
    ...stops.flat(),
  ] as unknown as number;
}

/**
 * Builds a complete MapLibre style from resolved theme colours.
 *
 * `blank` drops the tile source and every layer that reads from it, leaving
 * just the ground colour — a canvas for data that supplies its own geography,
 * such as a choropleth or an arc diagram, where street detail underneath is
 * noise rather than context.
 */
export function buildBasemapStyle(
  tokens: BasemapTokens,
  options: { blank?: boolean; source?: BasemapSource } = {}
): StyleSpecification {
  const { blank = false, source = CARTO_SOURCE } = options;

  const ground = {
    id: 'ground',
    type: 'background',
    paint: { 'background-color': tokens.background },
  };

  if (blank) {
    return {
      version: 8,
      name: 'PanelUI blank',
      sources: {},
      layers: [ground],
    } as unknown as StyleSpecification;
  }

  const label = {
    'text-font': source.fonts,
    'text-max-width': 8,
  };

  const labelPaint = {
    'text-color': tokens.label,
    'text-halo-color': tokens.labelHalo,
    'text-halo-width': 1.2,
  };

  return {
    version: 8,
    name: 'PanelUI',
    glyphs: source.glyphs,
    sources: {
      [SOURCE_ID]: {
        type: 'vector',
        url: source.url,
        ...(source.attribution ? { attribution: source.attribution } : {}),
      },
    },
    layers: [
      ground,
      // Green space sits directly on the ground and everything else on top of
      // it, so a park never punches a hole through a road crossing it.
      {
        id: 'landcover',
        type: 'fill',
        source: SOURCE_ID,
        'source-layer': 'landcover',
        paint: { 'fill-color': tokens.land, 'fill-opacity': 0.7 },
      },
      {
        id: 'park',
        type: 'fill',
        source: SOURCE_ID,
        'source-layer': 'park',
        paint: { 'fill-color': tokens.land, 'fill-opacity': 0.7 },
      },
      {
        id: 'water',
        type: 'fill',
        source: SOURCE_ID,
        'source-layer': 'water',
        paint: { 'fill-color': tokens.water },
      },
      {
        id: 'waterway',
        type: 'line',
        source: SOURCE_ID,
        'source-layer': 'waterway',
        paint: {
          'line-color': tokens.water,
          'line-width': width([
            [8, 0.5],
            [16, 3],
          ]),
        },
      },
      // Buildings only from the zoom where they stop being a grey smear.
      {
        id: 'building',
        type: 'fill',
        source: SOURCE_ID,
        'source-layer': 'building',
        minzoom: 14,
        paint: { 'fill-color': tokens.building, 'fill-opacity': 0.8 },
      },
      // Roads as one line per class rather than a fill over a casing. At these
      // contrasts a casing is a second grey against the first and reads as a
      // blur, not as an edge.
      {
        id: 'road-minor',
        type: 'line',
        source: SOURCE_ID,
        'source-layer': 'transportation',
        minzoom: 12,
        filter: ['match', ['get', 'class'], ['minor', 'service', 'track'], true, false],
        paint: {
          'line-color': tokens.line,
          'line-width': width([
            [12, 0.4],
            [18, 6],
          ]),
        },
        layout: { 'line-cap': 'round', 'line-join': 'round' },
      },
      {
        id: 'road-secondary',
        type: 'line',
        source: SOURCE_ID,
        'source-layer': 'transportation',
        minzoom: 8,
        filter: ['match', ['get', 'class'], ['secondary', 'tertiary'], true, false],
        paint: {
          'line-color': tokens.line,
          'line-width': width([
            [8, 0.5],
            [18, 10],
          ]),
        },
        layout: { 'line-cap': 'round', 'line-join': 'round' },
      },
      {
        id: 'road-major',
        type: 'line',
        source: SOURCE_ID,
        'source-layer': 'transportation',
        filter: ['match', ['get', 'class'], ['motorway', 'trunk', 'primary'], true, false],
        paint: {
          'line-color': tokens.line,
          'line-width': width([
            [5, 0.5],
            [18, 14],
          ]),
        },
        layout: { 'line-cap': 'round', 'line-join': 'round' },
      },
      // Dashed, because a border is a claim rather than a thing on the ground.
      {
        id: 'boundary',
        type: 'line',
        source: SOURCE_ID,
        'source-layer': 'boundary',
        filter: ['<=', ['get', 'admin_level'], 4],
        paint: {
          'line-color': tokens.line,
          'line-dasharray': [2, 2],
          'line-width': width([
            [3, 0.6],
            [12, 1.8],
          ]),
        },
      },
      {
        id: 'water-label',
        type: 'symbol',
        source: SOURCE_ID,
        'source-layer': 'water_name',
        layout: { ...label, 'text-field': ['get', 'name'], 'text-size': 11 },
        paint: labelPaint,
      },
      {
        id: 'road-label',
        type: 'symbol',
        source: SOURCE_ID,
        'source-layer': 'transportation_name',
        minzoom: 14,
        layout: {
          ...label,
          'text-field': ['get', 'name'],
          'text-size': 10,
          'symbol-placement': 'line',
        },
        paint: labelPaint,
      },
      // Places last, so a city name is never hidden under a street name.
      {
        id: 'place-label',
        type: 'symbol',
        source: SOURCE_ID,
        'source-layer': 'place',
        layout: {
          ...label,
          'text-field': ['get', 'name'],
          // Cities carry more weight than villages, and the type is the only
          // thing distinguishing them once every label is the same colour.
          'text-size': [
            'match',
            ['get', 'class'],
            'city',
            14,
            'town',
            12,
            10,
          ],
        },
        paint: labelPaint,
      },
    ],
  } as unknown as StyleSpecification;
}

/**
 * Map — a themed vector map.
 *
 * Everything visible is built from theme tokens rather than shipped as a
 * finished style, so the map belongs to whatever theme is active instead of
 * being the one rectangle on the screen that stayed grey. See `basemap.ts` for
 * how the style is assembled; the short version is that the tiles are bought
 * and the colours are ours.
 *
 * ```tsx
 * <Map center={[-0.12, 51.5]} zoom={11}>
 *   <Map.Marker lngLat={[-0.12, 51.5]}>
 *     <Map.Popup>
 *       <Text weight="medium">Charing Cross</Text>
 *     </Map.Popup>
 *   </Map.Marker>
 *   <Map.Controls locate />
 * </Map>
 * ```
 *
 * The renderer is native and optional, so `Map` has a state no other component
 * here does: it may be unable to draw at all. It says so in place rather than
 * throwing, because the usual way to reach that state is running in a client
 * that cannot load native modules, and a screen explaining the build you need
 * is more use than a stack trace.
 *
 * `Map.Popup` reads its position from the marker it sits inside, the way a
 * frame's title reads its weight from its slot. Given a `lngLat` of its own it
 * anchors to that coordinate instead, so the same name covers both the popup
 * attached to a pin and the one floating over a place with no pin at all.
 */
import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { Pressable, View, type ViewProps } from 'react-native';
import { useCSSVariable } from 'uniwind';
import { tv } from 'tailwind-variants';
import { CompassIcon, CrosshairIcon, MinusIcon, PlusIcon } from '@/components/ui/icons';
import { Text } from '@/components/ui/text';
import { cn } from '@/lib/cn';
import {
  buildBasemapStyle,
  CARTO_SOURCE,
  type BasemapSource,
  type BasemapTokens,
} from '@/components/ui/basemap';
import {
  hasMapLibre,
  MapLibre,
  type CameraRef,
  type LngLat,
  type LngLatBounds,
  type MapRef,
  type StyleSpecification,
  type ViewState,
} from '@/components/ui/maplibre';

export { hasMapLibre, CARTO_SOURCE };
export type { BasemapSource, BasemapTokens, LngLat, LngLatBounds, ViewState };

const mapVariants = tv({
  slots: {
    root: 'flex-1 overflow-hidden',
    controls: 'absolute gap-2',
    // A control group is one surface split by hairlines rather than separate
    // buttons: at 36pt a gap between them reads as damage, not as spacing.
    group: 'overflow-hidden rounded-xl border border-border bg-card shadow-sm',
    control: 'h-9 w-9 items-center justify-center active:bg-muted',
    popup: 'rounded-xl border border-border bg-popover px-3 py-2 shadow-lg',
    pin: 'h-3.5 w-3.5 rounded-full border-2 border-background bg-primary shadow-md',
  },
  variants: {
    position: {
      'top-left': { controls: 'left-3 top-3' },
      'top-right': { controls: 'right-3 top-3' },
      'bottom-left': { controls: 'bottom-3 left-3' },
      'bottom-right': { controls: 'bottom-3 right-3' },
    },
  },
  defaultVariants: { position: 'bottom-right' },
});

export type MapControlsPosition =
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right';

/** Reads a theme token, falling back when it resolves to something unusable. */
function useToken(name: string, fallback: string): string {
  const value = useCSSVariable(name);
  return typeof value === 'string' && value.length > 0 ? value : fallback;
}

interface MapContextValue {
  mapRef: React.RefObject<MapRef | null>;
  cameraRef: React.RefObject<CameraRef | null>;
  /** The style has loaded and the map is drawing. */
  ready: boolean;
}

const MapContext = createContext<MapContextValue | null>(null);

/**
 * The map's camera and view state, from inside it.
 *
 * For a control, an overlay, or anything that has to move the map in response
 * to something that is not a gesture on it.
 */
export function useMap(): MapContextValue {
  const context = useContext(MapContext);
  if (!context) throw new Error('useMap must be used inside a <Map>.');
  return context;
}

/** Set by `Map.Marker`, so a popup inside one knows where it is. */
const MarkerContext = createContext<LngLat | null>(null);

export interface MapHandle {
  /** Move the camera, animating unless `duration` is 0. */
  flyTo(options: { center: LngLat; zoom?: number; duration?: number }): void;
  /** Frame a bounding box, leaving `padding` points around it. */
  fitBounds(bounds: LngLatBounds, padding?: number): void;
  /** Where the map is looking right now. */
  getViewState(): Promise<ViewState | null>;
}

export interface MapProps extends Omit<ViewProps, 'children'> {
  children?: ReactNode;
  /** Initial centre, `[longitude, latitude]`. */
  center?: LngLat;
  /** Initial zoom. 0 is the whole world; 18 is a building. */
  zoom?: number;
  /** Initial bearing in degrees, clockwise from north. */
  bearing?: number;
  /** Initial tilt in degrees. 0 looks straight down. */
  pitch?: number;
  /**
   * Frame these bounds instead of centring — `[west, south, east, north]`.
   * Wins over `center` and `zoom` when both are given.
   */
  bounds?: LngLatBounds;
  /**
   * Drop the basemap and keep only the ground colour. For data that carries
   * its own geography — a choropleth, an arc diagram — where streets
   * underneath are noise rather than context.
   */
  blank?: boolean;
  /**
   * Where the vector tiles come from. Defaults to CARTO, which is free for
   * non-commercial use and licensed for everything else.
   */
  source?: BasemapSource;
  /**
   * Use this style wholesale instead of building one from tokens. The escape
   * hatch for a map that has to match something outside the app.
   */
  mapStyle?: string | StyleSpecification;
  /** Let the map rotate and tilt. Off by default — most maps only pan and zoom. */
  rotatable?: boolean;
  /** Turn off panning and zooming, for a map that is an illustration. */
  interactive?: boolean;
  /** Fires continuously while the map moves. */
  onViewStateChange?: (state: ViewState) => void;
  /** Fires when the map is pressed somewhere that is not a feature. */
  onPress?: (lngLat: LngLat) => void;
  /** Fires once the style has loaded and the first frame is drawn. */
  onReady?: () => void;
}

/**
 * Shown when the renderer is missing. Deliberately explicit about the cause:
 * "map unavailable" sends people looking at their network, and the actual
 * problem is almost always a build that never included the native module.
 */
function MapUnavailable({ className, ...props }: ViewProps) {
  return (
    <View
      className={cn(
        'flex-1 items-center justify-center gap-1 rounded-2xl border border-dashed border-border bg-muted/25 p-6',
        className
      )}
      accessibilityRole="alert"
      {...props}
    >
      <Text size="sm" weight="medium">
        Map renderer not installed
      </Text>
      <Text size="xs" muted className="text-center">
        Map needs a development build. Install
        @maplibre/maplibre-react-native, add its config plugin, and rebuild —
        it cannot run in a client that loads no native modules.
      </Text>
    </View>
  );
}

const MapRoot = forwardRef<MapHandle, MapProps>(function MapRoot(
  {
    children,
    className,
    center,
    zoom = 2,
    bearing,
    pitch,
    bounds,
    blank = false,
    source = CARTO_SOURCE,
    mapStyle,
    rotatable = false,
    interactive = true,
    onViewStateChange,
    onPress,
    onReady,
    ...props
  },
  ref
) {
  const slots = mapVariants();
  const mapRef = useRef<MapRef | null>(null);
  const cameraRef = useRef<CameraRef | null>(null);
  const [ready, setReady] = useState(false);

  // Every colour the style needs, resolved from the active theme. Hooks run
  // unconditionally, so they sit above the renderer check rather than inside it.
  const tokens: BasemapTokens = {
    background: useToken('--color-background', '#ffffff'),
    water: useToken('--color-muted', 'rgba(0,0,0,0.06)'),
    land: useToken('--color-surface-secondary', 'rgba(0,0,0,0.04)'),
    building: useToken('--color-surface-tertiary', 'rgba(0,0,0,0.08)'),
    line: useToken('--color-border', 'rgba(0,0,0,0.1)'),
    label: useToken('--color-muted-foreground', '#686868'),
    labelHalo: useToken('--color-background', '#ffffff'),
  };

  const style = useMemo(
    () => mapStyle ?? buildBasemapStyle(tokens, { blank, source }),
    // The token object is rebuilt every render, so depend on its values.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      mapStyle,
      blank,
      source,
      tokens.background,
      tokens.water,
      tokens.land,
      tokens.building,
      tokens.line,
      tokens.label,
      tokens.labelHalo,
    ]
  );

  useImperativeHandle(
    ref,
    () => ({
      flyTo: ({ center: to, zoom: z, duration = 900 }) =>
        cameraRef.current?.flyTo({ center: to, zoom: z, duration }),
      fitBounds: (box, padding = 48) =>
        cameraRef.current?.fitBounds(
          [box[2], box[3]],
          [box[0], box[1]],
          padding,
          900
        ),
      getViewState: async () => (await mapRef.current?.getViewState()) ?? null,
    }),
    []
  );

  const context = useMemo(() => ({ mapRef, cameraRef, ready }), [ready]);

  if (!hasMapLibre || !MapLibre) {
    return <MapUnavailable className={className} {...props} />;
  }

  const { Map: MapLibreMap, Camera } = MapLibre;

  return (
    <View className={slots.root({ className })} {...props}>
      <MapContext.Provider value={context}>
        <MapLibreMap
          ref={mapRef}
          mapStyle={style}
          style={{ flex: 1 }}
          // The library's own ornaments are turned off across the board:
          // they are drawn by the renderer in its own style and cannot be
          // themed, so `Map.Controls` replaces them with views that can.
          logo={false}
          compass={false}
          attribution={false}
          scaleBar={false}
          dragPan={interactive}
          touchZoom={interactive}
          touchRotate={rotatable}
          touchPitch={rotatable}
          onDidFinishLoadingMap={() => {
            setReady(true);
            onReady?.();
          }}
          onRegionDidChange={
            onViewStateChange
              ? (event) => onViewStateChange(event.nativeEvent)
              : undefined
          }
          onPress={
            onPress
              ? (event) => onPress(event.nativeEvent.coordinates)
              : undefined
          }
        >
          <Camera
            ref={cameraRef}
            defaultSettings={
              bounds
                ? { bounds }
                : { center: center ?? [0, 20], zoom, bearing, pitch }
            }
          />
          {children}
        </MapLibreMap>
      </MapContext.Provider>
    </View>
  );
});
MapRoot.displayName = 'Map';

export interface MapMarkerProps {
  /** Where the marker sits, `[longitude, latitude]`. */
  lngLat: LngLat;
  /**
   * Which part of the marker sits on the coordinate. A pin drawn above its
   * point wants `bottom`; a dot centred on it wants the default.
   */
  anchor?: 'center' | 'top' | 'bottom' | 'left' | 'right';
  /** Pressing the marker. Adds a button role when given. */
  onPress?: () => void;
  className?: string;
  /** Defaults to a dot. Anything else replaces it. */
  children?: ReactNode;
}

/**
 * A point on the map, drawn as React views rather than as a style layer — so
 * it can be anything the rest of the library can draw. For hundreds of points
 * use `Map.Cluster` instead: a view per marker stops being affordable long
 * before the map stops being readable.
 */
function MapMarker({
  lngLat,
  anchor = 'center',
  onPress,
  className,
  children,
}: MapMarkerProps) {
  const slots = mapVariants();

  if (!MapLibre) return null;
  const { Marker } = MapLibre;

  const body = (
    <View className={cn('items-center', className)}>
      {children ?? <View className={slots.pin()} />}
    </View>
  );

  return (
    <MarkerContext.Provider value={lngLat}>
      <Marker lngLat={lngLat} anchor={anchor}>
        {onPress ? (
          <Pressable accessibilityRole="button" onPress={onPress}>
            {body}
          </Pressable>
        ) : (
          body
        )}
      </Marker>
    </MarkerContext.Provider>
  );
}
MapMarker.displayName = 'Map.Marker';

export interface MapLabelProps {
  children?: ReactNode;
  className?: string;
  /** Which side of the marker the label sits on. */
  side?: 'top' | 'bottom';
}

/**
 * A caption pinned to a marker. Always visible, unlike a popup — for the
 * handful of places whose names are the point of the map.
 */
function MapLabel({ children, className, side = 'bottom' }: MapLabelProps) {
  return (
    <View
      className={cn(
        'rounded-md bg-background/85 px-1.5 py-0.5',
        side === 'top' ? 'mb-1' : 'mt-1',
        className
      )}
    >
      {typeof children === 'string' ? (
        <Text size="xs" weight="medium">
          {children}
        </Text>
      ) : (
        children
      )}
    </View>
  );
}
MapLabel.displayName = 'Map.Label';

export interface MapPopupProps {
  children?: ReactNode;
  className?: string;
  /** Heading above the content. Strings are wrapped for you. */
  title?: string;
  /**
   * Anchor to this coordinate instead of to an enclosing marker. Required when
   * the popup is not inside one.
   */
  lngLat?: LngLat;
}

/**
 * A card anchored to a point.
 *
 * Inside a `Map.Marker` it attaches to that marker and opens when it is
 * pressed. Given a `lngLat` it stands alone at that coordinate — the same
 * component either way, because the difference is where it is anchored rather
 * than what it is.
 */
function MapPopup({ children, className, title, lngLat }: MapPopupProps) {
  const slots = mapVariants();
  const markerLngLat = useContext(MarkerContext);
  const coordinate = lngLat ?? markerLngLat;

  if (!MapLibre) return null;
  const { Callout, Marker } = MapLibre;

  const body = (
    <View className={slots.popup({ className })}>
      {title ? (
        <Text size="sm" weight="medium">
          {title}
        </Text>
      ) : null}
      {children}
    </View>
  );

  // Inside a marker the renderer owns the show/hide, so this is a Callout.
  // Standalone it is its own marker, because a callout with nothing to hang
  // off has nowhere to be.
  if (markerLngLat && !lngLat) return <Callout>{body}</Callout>;
  if (!coordinate) return null;

  return (
    <Marker lngLat={coordinate} anchor="bottom">
      {body}
    </Marker>
  );
}
MapPopup.displayName = 'Map.Popup';

export interface MapControlsProps {
  /** Which corner the stack sits in. */
  position?: MapControlsPosition;
  /** Zoom in and out. On by default — it is the one control a map always needs. */
  zoom?: boolean;
  /** Recentre on the device's location. Needs a location permission. */
  locate?: boolean;
  /** Reset bearing and pitch to north and flat. */
  compass?: boolean;
  className?: string;
  /** Called with the located coordinate, so a caller can react to it. */
  onLocate?: (lngLat: LngLat) => void;
}

function ControlButton({
  label,
  onPress,
  children,
}: {
  label: string;
  onPress: () => void;
  children: ReactNode;
}) {
  const slots = mapVariants();
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={label}
      className={slots.control()}
      onPress={onPress}
    >
      {children}
    </Pressable>
  );
}

/**
 * The map's own chrome, as themed views.
 *
 * The renderer draws its own zoom and compass ornaments, but in its style
 * rather than the app's, and they cannot be recoloured — so they are turned
 * off in `Map` and replaced here by buttons built from the same tokens as
 * every other control in the library.
 */
function MapControls({
  position = 'bottom-right',
  zoom = true,
  locate = false,
  compass = false,
  className,
  onLocate,
}: MapControlsProps) {
  const slots = mapVariants({ position });
  const { mapRef, cameraRef } = useMap();

  // Read the live zoom rather than tracking it in state: the map is moved by
  // gestures too, and a counter kept alongside it drifts on the first pinch.
  const nudgeZoom = useCallback(
    async (delta: number) => {
      const map = mapRef.current;
      const camera = cameraRef.current;
      if (!map || !camera) return;
      const [center, current] = await Promise.all([
        map.getCenter(),
        map.getZoom(),
      ]);
      camera.easeTo({
        center,
        zoom: Math.min(22, Math.max(0, current + delta)),
        duration: 250,
      });
    },
    [mapRef, cameraRef]
  );

  const handleLocate = useCallback(async () => {
    let position$: { coords: { longitude: number; latitude: number } } | null =
      null;
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const location = require('expo-location');
      const granted = await location.requestForegroundPermissionsAsync();
      if (!granted?.granted) return;
      position$ = await location.getCurrentPositionAsync({});
    } catch {
      return;
    }
    if (!position$) return;
    const lngLat: LngLat = [
      position$.coords.longitude,
      position$.coords.latitude,
    ];
    cameraRef.current?.flyTo({ center: lngLat, zoom: 14, duration: 900 });
    onLocate?.(lngLat);
  }, [cameraRef, onLocate]);

  const resetNorth = useCallback(async () => {
    const center = await mapRef.current?.getCenter();
    if (!center) return;
    cameraRef.current?.easeTo({ center, bearing: 0, pitch: 0, duration: 300 });
  }, [mapRef, cameraRef]);

  return (
    <View className={slots.controls({ className })}>
      {zoom ? (
        <View className={slots.group()}>
          <ControlButton label="Zoom in" onPress={() => nudgeZoom(1)}>
            <PlusIcon size={16} />
          </ControlButton>
          <View className="h-px bg-border" />
          <ControlButton label="Zoom out" onPress={() => nudgeZoom(-1)}>
            <MinusIcon size={16} />
          </ControlButton>
        </View>
      ) : null}
      {compass ? (
        <View className={slots.group()}>
          <ControlButton label="Face north" onPress={resetNorth}>
            <CompassIcon size={16} />
          </ControlButton>
        </View>
      ) : null}
      {locate ? (
        <View className={slots.group()}>
          <ControlButton label="Show my location" onPress={handleLocate}>
            <CrosshairIcon size={16} />
          </ControlButton>
        </View>
      ) : null}
    </View>
  );
}
MapControls.displayName = 'Map.Controls';

/** Turns a token into a colour a style layer can use. */
function useLineColor(color?: string) {
  const fallback = useToken('--color-primary', '#262626');
  return color ?? fallback;
}

export interface MapRouteProps {
  /** The path, in order. */
  coordinates: LngLat[];
  /** Defaults to the primary token. */
  color?: string;
  /** Line thickness in points. */
  width?: number;
  /** Draw it dashed — for a leg that is planned rather than travelled. */
  dashed?: boolean;
  /** 0 is invisible, 1 is solid. */
  opacity?: number;
  id?: string;
}

/**
 * A path across the map, drawn as a style layer rather than as views — so its
 * cost does not grow with the number of points in it.
 */
function MapRoute({
  coordinates,
  color,
  width = 3,
  dashed = false,
  opacity = 1,
  id = 'route',
}: MapRouteProps) {
  const stroke = useLineColor(color);
  const data = useMemo(
    () => ({
      type: 'Feature' as const,
      properties: {},
      geometry: { type: 'LineString' as const, coordinates },
    }),
    [coordinates]
  );

  if (!MapLibre) return null;
  const { GeoJSONSource, Layer } = MapLibre;

  return (
    <GeoJSONSource id={`${id}-source`} data={data} lineMetrics>
      <Layer
        id={id}
        type="line"
        style={{
          lineColor: stroke,
          lineWidth: width,
          lineOpacity: opacity,
          lineCap: 'round',
          lineJoin: 'round',
          ...(dashed ? { lineDasharray: [2, 1.5] } : {}),
        }}
      />
    </GeoJSONSource>
  );
}
MapRoute.displayName = 'Map.Route';

export interface MapArcProps {
  /** Where the arc starts. */
  from: LngLat;
  /** Where it ends. */
  to: LngLat;
  /** How far it bows. 0 is a straight line; 0.2 is the default lift. */
  curvature?: number;
  color?: string;
  width?: number;
  opacity?: number;
  id?: string;
}

/**
 * A curved connection between two points.
 *
 * The curve is not geography — a great circle between two cities is not bowed
 * on a flat projection. It is there so that two arcs sharing an endpoint stay
 * tellable apart, which a bundle of straight lines through one city does not.
 */
function MapArc({
  from,
  to,
  curvature = 0.2,
  color,
  width = 2,
  opacity = 0.9,
  id = 'arc',
}: MapArcProps) {
  const stroke = useLineColor(color);

  const data = useMemo(() => {
    // A quadratic Bézier whose control point is pushed off the midpoint
    // perpendicular to the line, so the bow scales with the distance rather
    // than being a fixed lift that vanishes on long hops.
    const [x1, y1] = from;
    const [x2, y2] = to;
    const midX = (x1 + x2) / 2;
    const midY = (y1 + y2) / 2;
    const controlX = midX - (y2 - y1) * curvature;
    const controlY = midY + (x2 - x1) * curvature;

    const SEGMENTS = 64;
    const coordinates: LngLat[] = [];
    for (let i = 0; i <= SEGMENTS; i += 1) {
      const t = i / SEGMENTS;
      const inv = 1 - t;
      coordinates.push([
        inv * inv * x1 + 2 * inv * t * controlX + t * t * x2,
        inv * inv * y1 + 2 * inv * t * controlY + t * t * y2,
      ]);
    }
    return {
      type: 'Feature' as const,
      properties: {},
      geometry: { type: 'LineString' as const, coordinates },
    };
  }, [from, to, curvature]);

  if (!MapLibre) return null;
  const { GeoJSONSource, Layer } = MapLibre;

  return (
    <GeoJSONSource id={`${id}-source`} data={data} lineMetrics>
      <Layer
        id={id}
        type="line"
        style={{
          lineColor: stroke,
          lineWidth: width,
          lineOpacity: opacity,
          lineCap: 'round',
        }}
      />
    </GeoJSONSource>
  );
}
MapArc.displayName = 'Map.Arc';

export interface MapGeoJSONProps {
  /** A Feature, FeatureCollection, or the URL of one. */
  data: unknown;
  /** Fill colour for polygons. A style expression works here too. */
  fill?: string | unknown[];
  /** Outline colour. Defaults to the border token. */
  stroke?: string | unknown[];
  /** Outline thickness. */
  strokeWidth?: number;
  /** 0 is invisible, 1 is solid. */
  fillOpacity?: number;
  /** Fires with the pressed feature. */
  onPress?: (feature: unknown) => void;
  id?: string;
}

/**
 * Arbitrary geography as a themed layer — the component behind a choropleth,
 * a coverage area, or any other shape that comes from data rather than from
 * the basemap.
 *
 * `fill` takes a style expression as well as a colour, which is what makes a
 * choropleth one layer instead of one layer per bucket.
 */
function MapGeoJSON({
  data,
  fill,
  stroke,
  strokeWidth = 1,
  fillOpacity = 0.7,
  onPress,
  id = 'geojson',
}: MapGeoJSONProps) {
  const defaultFill = useToken('--color-primary', '#262626');
  const defaultStroke = useToken('--color-border', 'rgba(0,0,0,0.1)');

  if (!MapLibre) return null;
  const { GeoJSONSource, Layer } = MapLibre;

  return (
    <GeoJSONSource
      id={`${id}-source`}
      data={data}
      onPress={
        onPress
          ? (event) => onPress(event.nativeEvent.features?.[0])
          : undefined
      }
    >
      <Layer
        id={`${id}-fill`}
        type="fill"
        style={{
          fillColor: fill ?? defaultFill,
          fillOpacity,
        }}
      />
      <Layer
        id={`${id}-line`}
        type="line"
        style={{
          lineColor: stroke ?? defaultStroke,
          lineWidth: strokeWidth,
        }}
      />
    </GeoJSONSource>
  );
}
MapGeoJSON.displayName = 'Map.GeoJSON';

export interface MapClusterProps {
  /** Point features to cluster. */
  data: unknown;
  /** Defaults to the primary token. */
  color?: string;
  /** Text colour inside a cluster bubble. */
  textColor?: string;
  /** How close two points have to be, in points, to merge. */
  radius?: number;
  /** Above this zoom every point stands alone. */
  maxZoom?: number;
  /** Fires with the pressed cluster or point. */
  onPress?: (feature: unknown) => void;
  id?: string;
}

/**
 * Dense points, merged as they get too close to tell apart.
 *
 * This is the layer to reach for past a few dozen points: `Map.Marker` mounts
 * a React view each, which a thousand points cannot afford, and a thousand
 * overlapping pins would be unreadable even if it could.
 */
function MapCluster({
  data,
  color,
  textColor,
  radius = 50,
  maxZoom = 14,
  onPress,
  id = 'cluster',
}: MapClusterProps) {
  const fill = useToken('--color-primary', '#262626');
  const onFill = useToken('--color-primary-foreground', '#fafafa');
  const bubble = color ?? fill;
  const ink = textColor ?? onFill;

  if (!MapLibre) return null;
  const { GeoJSONSource, Layer } = MapLibre;

  return (
    <GeoJSONSource
      id={`${id}-source`}
      data={data}
      cluster
      clusterRadius={radius}
      clusterMaxZoom={maxZoom}
      onPress={
        onPress
          ? (event) => onPress(event.nativeEvent.features?.[0])
          : undefined
      }
    >
      {/* Bubbles grow in steps rather than continuously: the point is to read
          "more than that one", not to estimate a count from an area. */}
      <Layer
        id={`${id}-bubble`}
        type="circle"
        filter={['has', 'point_count']}
        style={{
          circleColor: bubble,
          circleRadius: ['step', ['get', 'point_count'], 16, 25, 22, 100, 28],
          circleStrokeWidth: 2,
          circleStrokeColor: ink,
          circleStrokeOpacity: 0.25,
        }}
      />
      <Layer
        id={`${id}-count`}
        type="symbol"
        filter={['has', 'point_count']}
        style={{
          textField: ['get', 'point_count_abbreviated'],
          textSize: 12,
          textColor: ink,
        }}
      />
      <Layer
        id={`${id}-point`}
        type="circle"
        filter={['!', ['has', 'point_count']]}
        style={{
          circleColor: bubble,
          circleRadius: 6,
          circleStrokeWidth: 2,
          circleStrokeColor: ink,
          circleStrokeOpacity: 0.4,
        }}
      />
    </GeoJSONSource>
  );
}
MapCluster.displayName = 'Map.Cluster';

export interface MapHeatmapProps {
  /** Point features to spread. */
  data: unknown;
  /** Feature property to weight each point by. Unweighted when omitted. */
  weight?: string;
  /** Spread of a single point, in points. Larger blurs more. */
  radius?: number;
  /** Overall strength. Raise it when the data is sparse. */
  intensity?: number;
  /** 0 is invisible, 1 is solid. */
  opacity?: number;
  /** Above this zoom the layer fades out — see the note on the component. */
  maxZoom?: number;
  id?: string;
}

/**
 * Point density as a continuous field.
 *
 * The opposite trade to `Map.Cluster`: a cluster keeps every point countable
 * and tells you nothing about the space between them, while a heatmap shows
 * the shape of the distribution and no longer lets you count anything. Reach
 * for it when the question is *where* rather than *how many*.
 *
 * It fades out past `maxZoom` on purpose. Zoomed far enough in, every point is
 * its own island and the blur says less than the points would — so the layer
 * gets out of the way rather than smearing five records across a street.
 */
function MapHeatmap({
  data,
  weight,
  radius = 24,
  intensity = 1,
  opacity = 0.85,
  maxZoom = 15,
  id = 'heatmap',
}: MapHeatmapProps) {
  const cool = useToken('--color-muted', 'rgba(0,0,0,0.06)');
  const warm = useToken('--color-chart-1', '#262626');
  const hot = useToken('--color-chart-2', '#666666');

  if (!MapLibre) return null;
  const { GeoJSONSource, Layer } = MapLibre;

  return (
    <GeoJSONSource id={`${id}-source`} data={data}>
      <Layer
        id={id}
        type="heatmap"
        maxzoom={maxZoom}
        style={{
          heatmapWeight: weight
            ? ['interpolate', ['linear'], ['get', weight], 0, 0, 1, 1]
            : 1,
          heatmapIntensity: intensity,
          heatmapRadius: radius,
          // Transparent at zero rather than the coolest colour, so the map
          // shows through everywhere nothing was measured instead of the whole
          // viewport being tinted by the absence of data.
          heatmapColor: [
            'interpolate',
            ['linear'],
            ['heatmap-density'],
            0,
            'rgba(0,0,0,0)',
            0.2,
            cool,
            0.6,
            warm,
            1,
            hot,
          ],
          heatmapOpacity: [
            'interpolate',
            ['linear'],
            ['zoom'],
            maxZoom - 2,
            opacity,
            maxZoom,
            0,
          ],
        }}
      />
    </GeoJSONSource>
  );
}
MapHeatmap.displayName = 'Map.Heatmap';

export interface MapUserLocationProps {
  /** Show which way the device is facing, not just where it is. */
  heading?: boolean;
}

/** The device's own position, drawn by the renderer. */
function MapUserLocation({ heading = false }: MapUserLocationProps) {
  if (!MapLibre) return null;
  const { UserLocation } = MapLibre;
  return <UserLocation visible showsUserHeadingIndicator={heading} />;
}
MapUserLocation.displayName = 'Map.UserLocation';

export const Map = Object.assign(MapRoot, {
  Marker: MapMarker,
  Label: MapLabel,
  Popup: MapPopup,
  Controls: MapControls,
  Route: MapRoute,
  Arc: MapArc,
  GeoJSON: MapGeoJSON,
  Cluster: MapCluster,
  Heatmap: MapHeatmap,
  UserLocation: MapUserLocation,
});

/**
 * The bridge to MapLibre.
 *
 * A map is the one component here that cannot be drawn in JavaScript. It needs
 * a renderer with the tiles, the projection and the GPU work already solved,
 * and that renderer is native code — which means `Map` is the only component
 * in the library with a dependency you have to build for.
 *
 * Two things follow, and both are handled here rather than spread through the
 * component:
 *
 * The package is resolved lazily and once. A project that never renders a map
 * installs nothing, and the failure when it is missing is a readable fallback
 * rather than a red screen — which matters because the most common way to hit
 * it is running in a client that cannot load native modules at all.
 *
 * The types are declared here rather than imported from the package. They are
 * structural and cover only what is used. Importing them would put the package
 * in the library's published type surface, so anyone installing PanelUI would
 * have to install a map renderer to typecheck their project, whether or not
 * they ever draw a map.
 */
import type { ComponentType, ReactElement, ReactNode, Ref } from 'react';

/** `[longitude, latitude]` — the order the style spec uses, not the spoken one. */
export type LngLat = [number, number];

/** `[west, south, east, north]`. */
export type LngLatBounds = [number, number, number, number];

/**
 * A MapLibre style document. Left loose on purpose: the spec is large, it is
 * versioned separately from this library, and the parts of it callers pass
 * through are exactly the parts a narrower type would get in the way of.
 */
export type StyleSpecification = Record<string, unknown>;

/** Where the map is looking. */
export interface ViewState {
  center: LngLat;
  zoom: number;
  bearing: number;
  pitch: number;
  bounds: LngLatBounds;
}

export interface MapRef {
  getCenter(): Promise<LngLat>;
  getZoom(): Promise<number>;
  getBearing(): Promise<number>;
  getPitch(): Promise<number>;
  getBounds(): Promise<LngLatBounds>;
  getViewState(): Promise<ViewState>;
}

export interface CameraRef {
  jumpTo(options: Record<string, unknown>): void;
  easeTo(options: Record<string, unknown>): void;
  flyTo(options: Record<string, unknown>): void;
  fitBounds(
    northEast: LngLat,
    southWest: LngLat,
    padding?: number | number[],
    duration?: number
  ): void;
}

/** A native event as it arrives — the payload is under `nativeEvent`. */
export interface NativeEvent<T> {
  nativeEvent: T;
}

interface MapLibreModule {
  Map: ComponentType<{
    ref?: Ref<MapRef>;
    mapStyle: string | StyleSpecification;
    style?: unknown;
    logo?: boolean;
    compass?: boolean;
    attribution?: boolean;
    scaleBar?: boolean;
    dragPan?: boolean;
    touchZoom?: boolean;
    touchRotate?: boolean;
    touchPitch?: boolean;
    onPress?: (event: NativeEvent<{ coordinates: LngLat }>) => void;
    onDidFinishLoadingMap?: () => void;
    onRegionDidChange?: (event: NativeEvent<ViewState>) => void;
    children?: ReactNode;
  }>;
  Camera: ComponentType<{
    ref?: Ref<CameraRef>;
    defaultSettings?: Record<string, unknown>;
    center?: LngLat;
    bounds?: LngLatBounds;
    zoom?: number;
    bearing?: number;
    pitch?: number;
    padding?: Record<string, number>;
    animationDuration?: number;
    animationMode?: 'linear' | 'ease' | 'fly';
  }>;
  Marker: ComponentType<{
    id?: string;
    lngLat: LngLat;
    anchor?: string;
    children: ReactElement;
  }>;
  Callout: ComponentType<{ title?: string; children?: ReactNode; style?: unknown }>;
  GeoJSONSource: ComponentType<{
    id?: string;
    data: unknown;
    cluster?: boolean;
    clusterRadius?: number;
    clusterMaxZoom?: number;
    lineMetrics?: boolean;
    onPress?: (event: NativeEvent<{ features: unknown[] }>) => void;
    children?: ReactNode;
  }>;
  Layer: ComponentType<Record<string, unknown>>;
  UserLocation: ComponentType<{ visible?: boolean; showsUserHeadingIndicator?: boolean }>;
}

/**
 * The renderer, or null when it is not installed. Resolved once at module
 * load — the require is cheap, and caching it keeps a try/catch out of render.
 */
const maplibre: MapLibreModule | null = (() => {
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    return require('@maplibre/maplibre-react-native') as MapLibreModule;
  } catch {
    return null;
  }
})();

/**
 * True when a map can actually be drawn.
 *
 * False in any client that cannot load native modules, and in any project that
 * has not installed the renderer. Worth checking before routing somewhere whose
 * whole content is a map.
 */
export const hasMapLibre = maplibre !== null;

/**
 * The renderer's components, or null.
 *
 * Returned as one object rather than as separate exports so a caller destructures
 * once after a single null check, instead of narrowing each component in turn.
 */
export const MapLibre = maplibre;
